import{_ as a,c as i,o as t,ag as s}from"./chunks/framework.Vyheyqg9.js";const m=JSON.parse('{"title":"What is accessibility?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/A11y/What_is_a11y.md","filePath":"senior_growth/A11y/What_is_a11y.md"}'),n={name:"senior_growth/A11y/What_is_a11y.md"};function r(o,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="what-is-accessibility" tabindex="-1">What is accessibility? <a class="header-anchor" href="#what-is-accessibility" aria-label="Permalink to “What is accessibility?”">​</a></h1><p><strong>a11y</strong> is short for <strong>accessibility</strong>—the practice of making websites, applications, and digital content usable by <strong>all people, including those with disabilities</strong>. The term comes from:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a11y → a + 11 letters + y → accessibility</span></span></code></pre></div><hr><h2 id="_1️⃣-purpose-of-a11y" tabindex="-1"><span class="hub-section-number">1 </span>Purpose of a11y <a class="header-anchor" href="#_1️⃣-purpose-of-a11y" aria-label="Permalink to “1 Purpose of a11y”">​</a></h2><p>Accessibility ensures that everyone can <strong>perceive, understand, navigate, and interact</strong> with digital content, including users with:</p><ul><li><strong>Visual impairments</strong> (blindness, low vision, color blindness)</li><li><strong>Hearing impairments</strong></li><li><strong>Motor or dexterity limitations</strong></li><li><strong>Cognitive or learning disabilities</strong></li><li>Temporary or situational limitations (e.g., bright sunlight, noisy environment)</li></ul><hr><h2 id="_2️⃣-key-principles-wcag-guidelines" tabindex="-1"><span class="hub-section-number">2 </span>Key Principles (WCAG Guidelines) <a class="header-anchor" href="#_2️⃣-key-principles-wcag-guidelines" aria-label="Permalink to “2 Key Principles (WCAG Guidelines)”">​</a></h2><ol><li><strong>Perceivable</strong> – Information must be available in forms users can perceive, including compatible text alternatives and assistive output. <ul><li>Example: Provide alt text for images, captions for videos.</li></ul></li><li><strong>Operable</strong> – Users must be able to <strong>interact with content</strong>. <ul><li>Example: Keyboard navigation, focus indicators.</li></ul></li><li><strong>Understandable</strong> – Content and UI must be <strong>comprehensible</strong>. <ul><li>Example: Clear language, consistent layouts.</li></ul></li><li><strong>Robust</strong> – Content must work with <strong>assistive technologies</strong>. <ul><li>Example: Proper semantic HTML, ARIA roles.</li></ul></li></ol><hr><h2 id="_3️⃣-benefits-of-a11y" tabindex="-1"><span class="hub-section-number">3 </span>Benefits of a11y <a class="header-anchor" href="#_3️⃣-benefits-of-a11y" aria-label="Permalink to “3 Benefits of a11y”">​</a></h2><ul><li><strong>Inclusion:</strong> Removes barriers for people with varied disabilities and access needs; an undated prevalence estimate is unnecessary to justify a usable task.</li><li><strong>Content structure:</strong> Useful semantics and alternatives can aid both people and content understanding; accessibility does not guarantee a search ranking.</li><li><strong>Usability for all:</strong> Improves experience for everyone (e.g., mobile users, older adults).</li><li><strong>Applicable obligations:</strong> Technical criteria, product scope and jurisdiction/contract requirements need an actual assessment; this introductory note makes no legal-compliance claim.</li></ul><hr><h3 id="✅-summary" tabindex="-1"><span class="hub-section-number">3.1 </span>Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “3.1 Summary”">​</a></h3><p><strong>a11y = accessibility.</strong><br> It’s about designing <strong>inclusive, usable, and robust experiences</strong> for all users, regardless of ability.</p><blockquote><p>Senior Tip: Accessibility should be <strong>built in from the start</strong>, not patched later. It improves <strong>quality, reach, and brand trust</strong>.</p></blockquote><h2 id="move-from-terminology-to-an-implemented-task" tabindex="-1"><span class="hub-section-number">4 </span>Move from terminology to an implemented task <a class="header-anchor" href="#move-from-terminology-to-an-implemented-task" aria-label="Permalink to “4 Move from terminology to an implemented task”">​</a></h2><p>Start with the <a href="./What_is_semantic_HTML.html">semantic HTML lesson</a>: a labeled native form, scoped landmarks, a sortable table with row/column headers, accessible name/description examples and an owned disclosure. Compare names, roles, states, keyboard operation and failure recovery rather than counting ARIA attributes. The <a href="./What_is_WCAG_standard__What_parts_it_contains_Web_Content_Accessibility_Guidelines.html#criteria-mapped-to-implementation-decisions">WCAG criterion matrix</a> connects these decisions to numbered criteria and a scoped evidence record.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">5 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “5 Separate practice”">​</a></h2><p>Apply the <a href="./../../practice/frontend/a11y/What_is_a11y.html">focused requirements and failure cases</a>. All learner practice remains outstanding; the worked examples above are explanatory material.</p>',21)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
